const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const sessionId = body.sessionId || ('session-' + Date.now());
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
const meta = body._meta || {};

if (!message || message.length < 1) throw new Error('Empty message');
if (message.length > 2000) throw new Error('Message too long');

return [{
  json: {
    message,
    sessionId,
    history,
    timestamp: new Date().toISOString(),
    source: meta.source || 'website-chat'
  }
}];

const llmResponse = $input.first().json;
const aiMessage = llmResponse.message?.content || llmResponse.choices?.[0]?.message?.content || 'I can help with that. Please tell me more about your needs.';
const userMessage = $('Validate & Prepare').first().json.message.toLowerCase();

// Detect intent
const bookingKeywords = ['book', 'schedule', 'appointment', 'meeting', 'call', 'consult', 'demo'];
const formKeywords = ['quote', 'proposal', 'price', 'cost', 'budget', 'get started', 'contact', 'reach out'];
const whatsappKeywords = ['whatsapp', 'chat', 'message', 'urgent', 'asap', 'immediately'];

const intent = bookingKeywords.some(k => userMessage.includes(k)) ? 'booking'
  : formKeywords.some(k => userMessage.includes(k)) ? 'form'
  : whatsappKeywords.some(k => userMessage.includes(k)) ? 'whatsapp'
  : 'continue';

return [{
  json: {
    aiMessage,
    intent,
    sessionId: $('Validate & Prepare').first().json.sessionId,
    timestamp: $('Validate & Prepare').first().json.timestamp
  }
}];

